const std = @import("std");
pub const CellId = usize;
pub const CallbackId = usize;
pub const Compute = *const fn ([]const i64) i64;
pub const CallbackFn = *const fn (*anyopaque, i64) void;
const Callback = struct { id: CallbackId, context: *anyopaque, function: CallbackFn };
const Cell = struct {
    value: i64,
    inputs: []CellId,
    scratch: []i64,
    compute: ?Compute,
    callbacks: std.array_list.Managed(Callback),
};
pub const Reactor = struct {
    allocator: std.mem.Allocator,
    cells: std.array_list.Managed(Cell),
    next_callback: CallbackId = 0,
    pub fn init(a: std.mem.Allocator) Reactor {
        return .{ .allocator = a, .cells = std.array_list.Managed(Cell).init(a) };
    }
    pub fn deinit(r: *Reactor) void {
        for (r.cells.items) |*cell| {
            r.allocator.free(cell.inputs);
            r.allocator.free(cell.scratch);
            cell.callbacks.deinit();
        }
        r.cells.deinit();
    }
    pub fn createInput(r: *Reactor, initial: i64) !CellId {
        try r.cells.append(.{ .value = initial, .inputs = &.{}, .scratch = &.{}, .compute = null, .callbacks = std.array_list.Managed(Callback).init(r.allocator) });
        return r.cells.items.len - 1;
    }
    pub fn createCompute(r: *Reactor, inputs: []const CellId, function: Compute) !CellId {
        for (inputs) |id| {
            if (id >= r.cells.items.len) return error.UnknownCell;
        }
        const ids = try r.allocator.dupe(CellId, inputs);
        errdefer r.allocator.free(ids);
        const scratch = try r.allocator.alloc(i64, inputs.len);
        errdefer r.allocator.free(scratch);
        for (inputs, scratch) |id, *v| v.* = r.cells.items[id].value;
        try r.cells.append(.{ .value = function(scratch), .inputs = ids, .scratch = scratch, .compute = function, .callbacks = std.array_list.Managed(Callback).init(r.allocator) });
        return r.cells.items.len - 1;
    }
    pub fn value(r: Reactor, id: CellId) !i64 {
        if (id >= r.cells.items.len) return error.UnknownCell;
        return r.cells.items[id].value;
    }
    pub fn setValue(r: *Reactor, id: CellId, value_: i64) !void {
        if (id >= r.cells.items.len) return error.UnknownCell;
        if (r.cells.items[id].compute != null) return error.NotInputCell;
        if (r.cells.items[id].value == value_) return;
        const old = try r.allocator.alloc(i64, r.cells.items.len);
        defer r.allocator.free(old);
        for (r.cells.items, old) |cell, *v| v.* = cell.value;
        r.cells.items[id].value = value_;
        // Every dependency predates its compute cell, so insertion order is topological.
        for (r.cells.items) |*cell| {
            if (cell.compute) |compute| {
                for (cell.inputs, cell.scratch) |input, *v| v.* = r.cells.items[input].value;
                cell.value = compute(cell.scratch);
            }
        }
        // Notify only after the graph has settled, once per changed output.
        for (r.cells.items, old) |cell, previous| {
            if (cell.value != previous) for (cell.callbacks.items) |callback| callback.function(callback.context, cell.value);
        }
    }
    pub fn addCallback(r: *Reactor, id: CellId, context: *anyopaque, function: CallbackFn) !CallbackId {
        if (id >= r.cells.items.len) return error.UnknownCell;
        if (r.cells.items[id].compute == null) return error.NotComputeCell;
        const callback_id = r.next_callback;
        try r.cells.items[id].callbacks.append(.{ .id = callback_id, .context = context, .function = function });
        r.next_callback += 1;
        return callback_id;
    }
    pub fn removeCallback(r: *Reactor, id: CellId, callback_id: CallbackId) void {
        if (id >= r.cells.items.len) return;
        const callbacks = &r.cells.items[id].callbacks;
        for (callbacks.items, 0..) |callback, i| {
            if (callback.id == callback_id) {
                _ = callbacks.orderedRemove(i);
                return;
            }
        }
    }
};

