const std = @import("std");
pub const CellId = usize;
pub const CallbackId = usize;
pub const Compute = *const fn ([]const i64) i64;
pub const CallbackFn = *const fn (*anyopaque, i64) void;
pub const Reactor = struct {
    pub fn init(a: std.mem.Allocator) Reactor {
        _ = a;
        return .{};
    }
    pub fn deinit(r: *Reactor) void {
        _ = r;
    }
    pub fn createInput(r: *Reactor, v: i64) !CellId {
        _ = r;
        _ = v;
        return 0;
    }
    pub fn createCompute(r: *Reactor, i: []const CellId, f: Compute) !CellId {
        _ = r;
        _ = i;
        _ = f;
        return 0;
    }
    pub fn value(r: Reactor, i: CellId) !i64 {
        _ = r;
        _ = i;
        return 0;
    }
    pub fn setValue(r: *Reactor, i: CellId, v: i64) !void {
        _ = r;
        _ = i;
        _ = v;
    }
    pub fn addCallback(r: *Reactor, i: CellId, c: *anyopaque, f: CallbackFn) !CallbackId {
        _ = r;
        _ = i;
        _ = c;
        _ = f;
        return 0;
    }
    pub fn removeCallback(r: *Reactor, i: CellId, c: CallbackId) void {
        _ = r;
        _ = i;
        _ = c;
    }
};

