// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("react.zig");
fn plus(v: []const i64) i64 {
    return v[0] + 1;
}
fn minus(v: []const i64) i64 {
    return v[0] - 1;
}
fn product(v: []const i64) i64 {
    return v[0] * v[1];
}
fn difference(v: []const i64) i64 {
    return v[0] - v[1];
}
fn ordered(v: []const i64) i64 {
    return v[0] + 10 * v[1];
}
const Observer = struct {
    calls: usize = 0,
    last: i64 = 0,
    fn callback(context: *anyopaque, value: i64) void {
        const o: *Observer = @ptrCast(@alignCast(context));
        o.calls += 1;
        o.last = value;
    }
};
test "input values ordered computation and errors" {
    var r = m.Reactor.init(t.allocator);
    defer r.deinit();
    const a = try r.createInput(1);
    const b = try r.createInput(2);
    const c = try r.createCompute(&.{ a, b }, ordered);
    try t.expectEqual(@as(i64, 21), try r.value(c));
    try r.setValue(a, 3);
    try t.expectEqual(@as(i64, 23), try r.value(c));
    try t.expectError(error.UnknownCell, r.value(100));
    try t.expectError(error.NotInputCell, r.setValue(c, 4));
    try t.expectError(error.UnknownCell, r.createCompute(&.{100}, plus));
}
test "diamond settles once and unchanged final outputs stay silent" {
    var r = m.Reactor.init(t.allocator);
    defer r.deinit();
    const input = try r.createInput(1);
    const p = try r.createCompute(&.{input}, plus);
    const n = try r.createCompute(&.{input}, minus);
    const n2 = try r.createCompute(&.{n}, minus);
    const out = try r.createCompute(&.{ p, n2 }, product);
    const constant = try r.createCompute(&.{ p, n }, difference);
    var a = Observer{};
    var b = Observer{};
    _ = try r.addCallback(out, &a, Observer.callback);
    _ = try r.addCallback(constant, &b, Observer.callback);
    try r.setValue(input, 4);
    try t.expectEqual(@as(i64, 10), try r.value(out));
    try t.expectEqual(@as(usize, 1), a.calls);
    try t.expectEqual(@as(i64, 10), a.last);
    try t.expectEqual(@as(usize, 0), b.calls);
    try r.setValue(input, 4);
    try t.expectEqual(@as(usize, 1), a.calls);
}
test "callbacks removal is independent and idempotent" {
    var r = m.Reactor.init(t.allocator);
    defer r.deinit();
    const input = try r.createInput(1);
    const out = try r.createCompute(&.{input}, plus);
    var a = Observer{};
    var b = Observer{};
    const first = try r.addCallback(out, &a, Observer.callback);
    _ = try r.addCallback(out, &b, Observer.callback);
    try r.setValue(input, 2);
    try t.expectEqual(@as(usize, 1), a.calls);
    try t.expectEqual(@as(usize, 1), b.calls);
    r.removeCallback(out, first);
    r.removeCallback(out, first);
    try r.setValue(input, 3);
    try t.expectEqual(@as(usize, 1), a.calls);
    try t.expectEqual(@as(usize, 2), b.calls);
}
